// Unifica eventos de diferentes canais em um schema padrão
const items = [];

for (const item of $input.all()) {
  let unifiedEvent = {
    channel: '',
    from: '',
    input_text: '',
    raw: item.json,
    timestamp: new Date().toISOString()
  };

  // Detecta o canal baseado na origem
  if (item.json.snippet || item.json.subject) {
    // Gmail
    unifiedEvent.channel = 'gmail';
    unifiedEvent.from = item.json.from || item.json.sender;
    unifiedEvent.input_text = item.json.snippet || item.json.bodyPlainText || '';
  } else if (item.json.data || item.json.message) {
    // WhatsApp via EvolutionAPI
    unifiedEvent.channel = 'whatsapp';
    unifiedEvent.from = item.json.data?.key?.remoteJid || item.json.from || '';

    // Extrai texto da mensagem
    if (item.json.data?.message?.conversation) {
      unifiedEvent.input_text = item.json.data.message.conversation;
    } else if (item.json.data?.message?.extendedTextMessage?.text) {
      unifiedEvent.input_text = item.json.data.message.extendedTextMessage.text;
    } else if (item.json.message?.text) {
      unifiedEvent.input_text = item.json.message.text;
    } else {
      // Para mídia (voz/imagem), sinaliza o tipo
      if (item.json.data?.message?.audioMessage) {
        unifiedEvent.input_text = '[AUDIO_MESSAGE_RECEIVED]';
      } else if (item.json.data?.message?.imageMessage) {
        unifiedEvent.input_text = '[IMAGE_MESSAGE_RECEIVED]';
      } else {
        unifiedEvent.input_text = '[UNKNOWN_MESSAGE_TYPE]';
      }
    }
  }

  // Normalização básica
  unifiedEvent.input_text = unifiedEvent.input_text.trim();

  items.push({
    json: unifiedEvent
  });
}

return items;

