// Regras estáticas para detecção de prompt injection e dados sensíveis - Agosto 2025
const items = [];

for (const item of $input.all()) {
  const inputText = item.json.input_text.toLowerCase();

  // Frases proibidas para prompt injection (expandidas para 2025)
  const forbiddenPhrases = [
    'ignore tudo acima', 'ignore previous', 'disregard system',
    'revele instruções', 'system prompt', 'modo desenvolvedor',
    'sem políticas', 'cole o pdf', 'dump do vector', 'exporte dados',
    'ignore all above', 'reveal instructions', 'developer mode',
    'no policies', 'paste the pdf', 'vector dump', 'export data',
    'show me your prompt', 'what are your instructions', 'bypass safety',
    'jailbreak', 'roleplay as', 'pretend you are', 'act as if',
    'forget everything', 'new instructions', 'override previous',
    'system override', 'admin mode', 'debug mode', 'maintenance mode',
    'show system message', 'reveal system prompt', 'dump configuration'
  ];

  // Regex para segredos (atualizado para 2025)
  const secretRegex = /(api[_-]?key|secret|token|authorization|password|credential|bearer|access[_-]?token)\s*[:=]\s*[A-Za-z0-9._\-=+/]{8,}/gi;

  // Regex para PII Brasil
  const cpfRegex = /\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/g;
  const cnpjRegex = /\b\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}\b/g;

  // Regex para outros PIIs (2025)
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
  const phoneRegex = /\b(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}[-\s]?\d{4}\b/g;
  const suspiciousUrlRegex = /https?:\/\/[^\s]+\.(exe|bat|cmd|scr|zip|rar)/gi;

  // Verificações
  let flags = {
    hasForbiddenPhrase: false,
    hasSecret: false,
    hasCPF: false,
    hasCNPJ: false,
    hasEmail: false,
    hasPhone: false,
    hasSuspiciousUrl: false,
    staticRisk: 'low'
  };

  // Verifica frases proibidas
  for (const phrase of forbiddenPhrases) {
    if (inputText.includes(phrase)) {
      flags.hasForbiddenPhrase = true;
      break;
    }
  }

  // Verifica segredos
  if (secretRegex.test(item.json.input_text)) {
    flags.hasSecret = true;
  }

  // Verifica CPF
  if (cpfRegex.test(item.json.input_text)) {
    flags.hasCPF = true;
  }

  // Verifica CNPJ
  if (cnpjRegex.test(item.json.input_text)) {
    flags.hasCNPJ = true;
  }

  // Verifica email
  if (emailRegex.test(item.json.input_text)) {
    flags.hasEmail = true;
  }

  // Verifica telefone
  if (phoneRegex.test(item.json.input_text)) {
    flags.hasPhone = true;
  }

  // Verifica URLs suspeitas
  if (suspiciousUrlRegex.test(item.json.input_text)) {
    flags.hasSuspiciousUrl = true;
  }

  // Determina risco estático
  if (flags.hasForbiddenPhrase || flags.hasSecret || flags.hasSuspiciousUrl) {
    flags.staticRisk = 'high';
  } else if (flags.hasCPF || flags.hasCNPJ || flags.hasEmail || flags.hasPhone) {
    flags.staticRisk = 'medium';
  }

  items.push({
    json: {
      ...item.json,
      staticFlags: flags
    }
  });
}

return items;

