// Sanitiza mensagens ambíguas com técnicas avançadas de 2025
const items = [];

for (const item of $input.all()) {
  const originalText = item.json.input_text;
  let processedItem = {
    ...item.json,
    decision: 'sanitize',
    was_sanitized: true,
    processing_timestamp: new Date().toISOString(),
    security_level: 'sanitized'
  };

  // Remove frases proibidas e padrões de 2025
  let sanitizedText = originalText
    .replace(/ignore\s+(tudo\s+acima|previous|all\s+above)/gi, '')
    .replace(/disregard\s+system/gi, '')
    .replace(/revel[ae]\s+instru[çc][õo]es/gi, '')
    .replace(/system\s+prompt/gi, '')
    .replace(/modo\s+desenvolvedor/gi, '')
    .replace(/developer\s+mode/gi, '')
    .replace(/sem\s+pol[íi]ticas/gi, '')
    .replace(/no\s+policies/gi, '')
    .replace(/cole\s+o\s+pdf/gi, '')
    .replace(/paste\s+the\s+pdf/gi, '')
    .replace(/dump\s+do\s+vector/gi, '')
    .replace(/vector\s+dump/gi, '')
    .replace(/export[ae]\s+dados/gi, '')
    .replace(/export\s+data/gi, '')
    .replace(/show\s+me\s+your\s+prompt/gi, '')
    .replace(/what\s+are\s+your\s+instructions/gi, '')
    .replace(/bypass\s+safety/gi, '')
    .replace(/jailbreak/gi, '')
    .replace(/roleplay\s+as/gi, '')
    .replace(/pretend\s+you\s+are/gi, '')
    .replace(/act\s+as\s+if/gi, '')
    .replace(/forget\s+everything/gi, '')
    .replace(/new\s+instructions/gi, '')
    .replace(/override\s+previous/gi, '')
    .replace(/system\s+override/gi, '')
    .replace(/admin\s+mode/gi, '')
    .replace(/debug\s+mode/gi, '')
    .replace(/maintenance\s+mode/gi, '')
    .replace(/show\s+system\s+message/gi, '')
    .replace(/reveal\s+system\s+prompt/gi, '')
    .replace(/dump\s+configuration/gi, '')
    .trim();

  // Remove possíveis dados sensíveis com padrões atualizados
  sanitizedText = sanitizedText
    .replace(/\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/g, '[CPF_REMOVIDO]')
    .replace(/\b\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}\b/g, '[CNPJ_REMOVIDO]')
    .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL_REMOVIDO]')
    .replace(/\b(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}[-\s]?\d{4}\b/g, '[TELEFONE_REMOVIDO]')
    .replace(/(api[_-]?key|secret|token|authorization|password|credential|bearer|access[_-]?token)\s*[:=]\s*[A-Za-z0-9._\-=+/]{8,}/gi, '[CREDENCIAL_REMOVIDA]')
    .replace(/https?:\/\/[^\s]+\.(exe|bat|cmd|scr|zip|rar)/gi, '[URL_SUSPEITA_REMOVIDA]');

  // Se ficou muito vazio, cria uma pergunta genérica contextual
  if (sanitizedText.length < 15) {
    sanitizedText = 'Você pode me ajudar com informações gerais sobre este tópico de forma segura?';
  }

  processedItem.input_text = sanitizedText;
  processedItem.original_text = originalText;
  processedItem.sanitization_applied = true;

  items.push({
    json: processedItem
  });
}

return items;

