// Guardrail de saída avançado - agosto 2025
const items = [];

for (const item of $input.all()) {
  let response = '';
  let isBlocked = false;
  let blockReason = '';

  // Se já foi negado, mantém a resposta de negação
  if (item.json.decision === 'deny') {
    items.push({
      json: {
        ...item.json,
        original_response: '',
        is_blocked: false,
        block_reason: 'Denied by decision switch',
        final_check_timestamp: new Date().toISOString()
      }
    });
    continue;
  }

  // Extrai a resposta do LLM (formato OpenAI nativo)
  if (item.json.response) {
    response = item.json.response;
  } else if (item.json.text) {
    response = item.json.text;
  } else {
    response = 'Desculpe, não foi possível processar sua solicitação no momento. Tente novamente.';
  }

  // Regex aprimorados para 2025 - detecção de vazamentos
  const secretRegex = /(api[_-]?key|secret|token|authorization|password|credential|bearer|access[_-]?token|private[_-]?key)\s*[:=]\s*[A-Za-z0-9._\-=+/]{8,}/gi;
  const cpfRegex = /\b\d{3}\.\d{3}\.\d{3}-\d{2}\b/g;
  const cnpjRegex = /\b\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}\b/g;
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
  const phoneRegex = /\b(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}[-\s]?\d{4}\b/g;
  const suspiciousUrlRegex = /https?:\/\/[^\s]+\.(exe|bat|cmd|scr|zip|rar|apk|dmg)/gi;

  // Padrões avançados de vazamento de prompt (2025)
  const promptLeakPatterns = [
    /você é um (classificador|assistente).{0,200}(sistema|prompt|instrução)/gi,
    /diretrizes de segurança.{0,100}(nunca|não)/gi,
    /nunca revele.{0,50}(informações|dados|prompt)/gi,
    /não compartilhe.{0,50}(dados|senhas|tokens)/gi,
    /mantenha as respostas.{0,50}(focadas|profissionais)/gi,
    /se a mensagem foi sanitizada/gi,
    /agosto de 2025.{0,50}(contexto|temporal)/gi,
    /system\s+prompt|system\s+message|internal\s+instructions/gi,
    /\[.*_REMOVIDO\]/gi,
    /processing_timestamp|security_level|was_sanitized/gi
  ];

  // Padrões de informações internas do sistema
  const internalInfoPatterns = [
    /n8n.{0,50}(workflow|node|function)/gi,
    /javascript.{0,50}(code|function|return)/gi,
    /const\s+items|return\s+items|\$json\./gi,
    /typeVersion|parameters|connections/gi
  ];

  // Verifica se a resposta contém informações sensíveis
  if (secretRegex.test(response)) {
    isBlocked = true;
    blockReason = 'Resposta contém possível segredo/token';
  } else if (cpfRegex.test(response)) {
    isBlocked = true;
    blockReason = 'Resposta contém CPF';
  } else if (cnpjRegex.test(response)) {
    isBlocked = true;
    blockReason = 'Resposta contém CNPJ';
  } else if (emailRegex.test(response)) {
    isBlocked = true;
    blockReason = 'Resposta contém email';
  } else if (phoneRegex.test(response)) {
    isBlocked = true;
    blockReason = 'Resposta contém telefone';
  } else if (suspiciousUrlRegex.test(response)) {
    isBlocked = true;
    blockReason = 'Resposta contém URL suspeita';
  } else {
    // Verifica vazamento de prompt
    for (const pattern of promptLeakPatterns) {
      if (pattern.test(response)) {
        isBlocked = true;
        blockReason = 'Possível vazamento de prompt detectado';
        break;
      }
    }

    // Verifica informações internas do sistema
    if (!isBlocked) {
      for (const pattern of internalInfoPatterns) {
        if (pattern.test(response)) {
          isBlocked = true;
          blockReason = 'Resposta contém informações internas do sistema';
          break;
        }
      }
    }
  }

  // Define resposta segura
  let safeResponse = '';
  if (isBlocked) {
    safeResponse = 'Não posso atender a este pedido devido a políticas de segurança. Posso fornecer um resumo de alto nível sem expor conteúdo interno, segredos ou dados pessoais. Como posso ajudá-lo de forma segura?';
  } else {
    safeResponse = response;
  }

  items.push({
    json: {
      ...item.json,
      original_response: response,
      safe_response: safeResponse,
      is_blocked: isBlocked,
      block_reason: blockReason,
      final_check_timestamp: new Date().toISOString(),
      guardrail_version: '2025.08'
    }
  });
}

return items;

