// Logger avançado para agosto 2025 - compliance e auditoria completa
const items = [];

for (const item of $input.all()) {
  let llmClassification = null;

  // Parse robusto da classificação LLM
  try {
    if (item.json.response) {
      const content = item.json.response.trim();
      // Remove possíveis caracteres extras e tenta múltiplos formatos
      const jsonMatch = content.match(/\{[^}]+\}/);
      if (jsonMatch) {
        llmClassification = JSON.parse(jsonMatch[0]);
      } else {
        llmClassification = JSON.parse(content);
      }
    }
  } catch (error) {
    console.log('Erro ao fazer parse da classificação LLM:', error.message);
    llmClassification = { 
      classe: 'parse_error', 
      confianca: 0,
      error: error.message,
      raw_content: item.json.response || 'N/A'
    };
  }

  // Calcula métricas de performance
  const processingTime = item.json.final_check_timestamp && item.json.timestamp ? 
    new Date(item.json.final_check_timestamp) - new Date(item.json.timestamp) : null;

  // Cria hash seguro para auditoria sem expor conteúdo (simulado)
  const createHash = (text) => {
    if (!text) return null;
    // Simulação de hash SHA-256 (primeiros 16 caracteres)
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      const char = text.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // Convert to 32bit integer
    }
    return Math.abs(hash).toString(16).substring(0, 16);
  };

  const inputHash = createHash(item.json.input_text);
  const outputHash = createHash(item.json.safe_response);

  const logEntry = {
    // Metadados do sistema
    timestamp: new Date().toISOString(),
    workflow_version: '2025.08',
    guardrail_version: item.json.guardrail_version || '2025.08',
    n8n_execution_id: $executionId || 'unknown',

    // Identificação da origem (hasheada para privacidade)
    channel: item.json.channel,
    from_hash: item.json.from ? createHash(item.json.from) : null,

    // Métricas de conteúdo (sem dados sensíveis)
    input_text_length: item.json.input_text ? item.json.input_text.length : 0,
    input_text_hash: inputHash,
    output_text_length: item.json.safe_response ? item.json.safe_response.length : 0,
    output_text_hash: outputHash,

    // Análise de risco e segurança
    static_risk_level: item.json.staticFlags ? item.json.staticFlags.staticRisk : 'unknown',
    static_flags_summary: {
      forbidden_phrase: item.json.staticFlags?.hasForbiddenPhrase || false,
      secret_detected: item.json.staticFlags?.hasSecret || false,
      pii_detected: (item.json.staticFlags?.hasCPF || item.json.staticFlags?.hasCNPJ || 
                     item.json.staticFlags?.hasEmail || item.json.staticFlags?.hasPhone) || false,
      suspicious_url: item.json.staticFlags?.hasSuspiciousUrl || false
    },
    llm_classification: llmClassification,

    // Decisões e processamento
    final_decision: item.json.decision || 'unknown',
    security_level: item.json.security_level || 'unknown',
    was_sanitized: item.json.was_sanitized || false,
    sanitization_applied: item.json.sanitization_applied || false,
    was_blocked_output: item.json.is_blocked || false,
    block_reason: item.json.block_reason || '',

    // Métricas de performance
    processing_time_ms: processingTime,

    // Timestamps detalhados para auditoria
    timestamps: {
      received: item.json.timestamp,
      processed: item.json.processing_timestamp,
      final_check: item.json.final_check_timestamp,
      logged: new Date().toISOString()
    },

    // Compliance e auditoria
    compliance_flags: {
      gdpr_compliant: true, // Dados hasheados
      lgpd_compliant: true, // Lei brasileira
      audit_trail_complete: !!(item.json.timestamp && item.json.final_check_timestamp),
      security_validated: !!(item.json.staticFlags && llmClassification)
    }
  };

  // Log estruturado para sistema de auditoria
  console.log('WORKFLOW_AUDIT_2025:', JSON.stringify(logEntry, null, 2));

  // Log resumido para monitoramento em tempo real
  const summary = `${logEntry.channel}|${logEntry.final_decision}|${logEntry.static_risk_level}|${logEntry.was_blocked_output}|${logEntry.processing_time_ms}ms|${logEntry.security_level}`;
  console.log('WORKFLOW_MONITOR_2025:', summary);

  // Log de alertas para casos de alto risco
  if (logEntry.static_risk_level === 'high' || logEntry.was_blocked_output || 
      (llmClassification && llmClassification.confianca > 0.8 && 
       ['override', 'exfiltracao', 'ilegal'].includes(llmClassification.classe))) {
    console.log('SECURITY_ALERT_2025:', JSON.stringify({
      timestamp: logEntry.timestamp,
      alert_type: 'high_risk_interaction',
      risk_level: logEntry.static_risk_level,
      classification: llmClassification?.classe,
      confidence: llmClassification?.confianca,
      blocked: logEntry.was_blocked_output,
      channel: logEntry.channel
    }));
  }

  items.push({
    json: {
      ...item.json,
      audit_log: logEntry
    }
  });
}

return items;
